nav_tabs_categorias.js:
(function(){
  var tabs = document.querySelectorAll('#catTabs .nav-link');
  var path = location.pathname + location.search;
  tabs.forEach(function(a){
    if(path === '/' && a.getAttribute('href') === '/'){a.classList.add('active');return;}
    if(a.getAttribute('href') !== '/' && path.indexOf(a.getAttribute('href')) === 0){a.classList.add('active');}else{a.classList.remove('active');}
  });
})();

breadcrumb_js.js:
(function(){
  var bc = document.getElementById('sl-breadcrumb');
  if(!bc) return;
  var path = location.pathname;
  var search = location.search;
  var label = search.match(/[?&]q=label\/([^&]+)/);
  if(label){
    var li = document.createElement('li');
    li.className = 'breadcrumb-item active';
    li.setAttribute('aria-current','page');
    li.textContent = decodeURIComponent(label[1]).replace(/-/g,' ');
    bc.appendChild(li);
    return;
  }
  var postTitleEl = document.querySelector('h1.post-title, h1.entry-title, h1.sl-post-title');
  if(postTitleEl && path !== '/'){
    var li = document.createElement('li');
    li.className = 'breadcrumb-item active';
    li.setAttribute('aria-current','page');
    li.textContent = postTitleEl.textContent.trim().slice(0,60);
    bc.appendChild(li);
  }
})();

filter_bar_labels.js:
(function(){
  var bar = document.getElementById('sl-label-filter');
  if(!bar) return;
  bar.querySelectorAll('.sl-filter-chip').forEach(function(btn){
    if(location.pathname === btn.dataset.href || location.href.indexOf(btn.dataset.href) > -1){
      bar.querySelectorAll('.sl-filter-chip').forEach(function(b){b.classList.remove('active');});
      btn.classList.add('active');
    }
    btn.addEventListener('click',function(){location.href=this.dataset.href;});
  });
})();
